import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
pt = ee.Geometry.Point([-117.80, 33.65])
geom = pt.buffer(5000)  # 5 km buffer inland near UCI Coastal Sage area

jan_start, jan_end = '2013-01-01', '2013-02-01'
may_start, may_end = '2013-05-01', '2013-06-01'

datasets = [
    {
        'id': 'ECMWF/ERA5_LAND/HOURLY',
        'band': 'volumetric_soil_water_layer_1',
        'scale': 9000
    },
    {
        'id': 'NASA/GLDAS/V021/NOAH/G025/T3H',
        'band': 'SoilMoi0_10cm_inst',
        'scale': 25000
    }
]

def month_stats(ds, start, end):
    col = (ee.ImageCollection(ds['id'])
           .filterDate(start, end)
           .filterBounds(geom)
           .select(ds['band']))
    size = col.size().getInfo()
    if size == 0:
        return {'status':'C1', 'size':0}
    img = col.mean()
    # Count valid pixels
    count = img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=ds['scale'],
        maxPixels=1e9
    ).get(ds['band']).getInfo()
    if count is None or int(count) == 0:
        return {'status':'C2', 'size':size, 'count': int(count) if count is not None else 0}
    # Mean value
    val = img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom,
        scale=ds['scale'],
        maxPixels=1e9
    ).get(ds['band']).getInfo()
    if val is None or (isinstance(val, float) and (math.isnan(val) or math.isinf(val))):
        return {'status':'C3', 'size':size, 'count':int(count)}
    return {'status':'OK', 'size':size, 'count':int(count), 'mean':float(val)}

try:
    chosen = None
    jan_res = may_res = None
    for ds in datasets:
        jan_res = month_stats(ds, jan_start, jan_end)
        may_res = month_stats(ds, may_start, may_end)
        # If both months are OK with valid pixels, choose this dataset
        if jan_res.get('status') == 'OK' and may_res.get('status') == 'OK':
            chosen = ds
            break

    # Handle failure cases across datasets
    if chosen is None:
        # Prioritize error codes according to spec
        if jan_res.get('status') == 'C1' or may_res.get('status') == 'C1':
            print("Dataset: None (empty collections after fallbacks)")
            print("<answer>C1</answer>")
        elif jan_res.get('status') == 'C2' or may_res.get('status') == 'C2':
            print("Dataset: Found images but no valid pixels after processing")
            print("<answer>C2</answer>")
        else:
            print("Dataset: Calculation failure")
            print("<answer>C3</answer>")
    else:
        # Print concise evidence
        print(f"Dataset: {chosen['id']} | Band: {chosen['band']}")
        print(f"Jan2013 Images: {jan_res['size']}, Valid px: {jan_res['count']}, Mean: {jan_res['mean']:.4f}")
        print(f"May2013 Images: {may_res['size']}, Valid px: {may_res['count']}, Mean: {may_res['mean']:.4f}")
        delta = jan_res['mean'] - may_res['mean']
        print(f"Delta(Jan-May): {delta:+.4f}")

        # Final decision
        if jan_res['mean'] is None or may_res['mean'] is None or not (math.isfinite(jan_res['mean']) and math.isfinite(may_res['mean'])):
            print("<answer>C3</answer>")
        elif delta > 0:
            print("<answer>A</answer>")
        else:
            print("<answer>B</answer>")

except Exception as e:
    # Any syntax/method/collection error or memory issue
    print(f"Error: {str(e)[:120]}")
    print("<answer>D</answer>")
